(7183649, 1103583, 30982, '<td valign="top">Has the church gone to the dogs, perhaps?  :-)  Very much like this in grays.</td>', 'Has the church gone to the dogs, perhaps?  :-)  Very much like this in grays.', '2014-03-01 21:29:08.000000', NULL, 1),
(7183650, 1103856, 30982, '<td valign="top">The triumvirate paused for only a moment, and the world moved on.</td>', 'The triumvirate paused for only a moment, and the world moved on.', '2014-03-01 21:29:35.000000', NULL, 1),
(7183652, 1103155, 30982, '<td valign="top">The little one is shy, yes?  Such expressive eyes!!</td>', 'The little one is shy, yes?  Such expressive eyes!!', '2014-03-01 21:29:55.000000', NULL, 1),
(7183653, 1103905, 30982, '<td valign="top">Lovely.  Simply lovely.</td>', 'Lovely.  Simply lovely.', '2014-03-01 21:30:19.000000', NULL, 1),
(7183654, 1103580, 30982, '<td valign="top">Nice motion and flow.</td>', 'Nice motion and flow.', '2014-03-01 21:30:30.000000', NULL, 1),
(7183655, 1102712, 30982, '<td valign="top">Almost impossibly perfect.</td>', 'Almost impossibly perfect.', '2014-03-01 21:30:58.000000', NULL, 1),
(7183656, 1102684, 30982, '<td valign="top">Has the feel of a pen and ink drawing.</td>', 'Has the feel of a pen and ink drawing.', '2014-03-01 21:31:16.000000', NULL, 1),
(7183658, 1102592, 30982, '<td valign="top">Not a pose one associates with a little one - almost as though she''s practicing for later in life.  Has a nice sense of ease.</td>', 'Not a pose one associates with a little one - almost as though she''s practicing for later in life.  Has a nice sense of ease.', '2014-03-01 21:32:14.000000', NULL, 1),
(7183659, 1104155, 30982, '<td valign="top">Ah, the red is just a bit too much for me.  I love the view, though!</td>', 'Ah, the red is just a bit too much for me.  I love the view, though!', '2014-03-01 21:32:54.000000', NULL, 1),
(7183660, 1102560, 30982, '<td valign="top">Nice anthropomorphism, or however you spell it, with the pose.  Nice light, too.</td>', 'Nice anthropomorphism, or however you spell it, with the pose.  Nice light, too.', '2014-03-01 21:34:38.000000', NULL, 1),
(7183661, 1104071, 30982, '<td valign="top">What light!!  A surreal world.</td>', 'What light!!  A surreal world.', '2014-03-01 21:35:24.000000', NULL, 1),
(7183662, 1104029, 30982, '<td valign="top">The overly digitized aspect adds a nice dimension to the otherwise normal flower picture.</td>', 'The overly digitized aspect adds a nice dimension to the otherwise normal flower picture.', '2014-03-01 21:36:08.000000', NULL, 1),
(7183663, 1103884, 30982, '<td valign="top">Adamsish.</td>', 'Adamsish.', '2014-03-01 21:37:00.000000', NULL, 1),
(7183665, 1103362, 30982, '<td valign="top">I so want to see this a bit bigger, to explore the dark nooks and crannies.  A very intriguing entry!</td>', 'I so want to see this a bit bigger, to explore the dark nooks and crannies.  A very intriguing entry!', '2014-03-01 21:37:50.000000', NULL, 1),
(7183666, 1104077, 30982, '<td valign="top">Ah yes!  Wonderful that you caught him just before he turned the corner and disappeared.</td>', 'Ah yes!  Wonderful that you caught him just before he turned the corner and disappeared.', '2014-03-01 21:38:47.000000', NULL, 1),
(7183667, 1103986, 30982, '<td valign="top">Enchanting and a bit melancholy.  Very nice!</td>', 'Enchanting and a bit melancholy.  Very nice!', '2014-03-01 21:39:10.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7183680, 1103345, 30982, '<td valign="top">What an entertaining collection of clouds!</td>', 'What an entertaining collection of clouds!', '2014-03-01 22:01:15.000000', NULL, 1),
(7183683, 1102596, 30982, '<td valign="top">Excellent color noise, and nice bit of yin yang as well.</td>', 'Excellent color noise, and nice bit of yin yang as well.', '2014-03-01 22:06:52.000000', NULL, 1),
(7183685, 1102839, 30982, '<td valign="top">I can feel the warmth of the sun, the coolness tinging the air.  Perfect.</td>', 'I can feel the warmth of the sun, the coolness tinging the air.  Perfect.', '2014-03-01 22:08:40.000000', NULL, 1),
(7183686, 1104169, 30982, '<td valign="top">Beautiful squigglies!!</td>', 'Beautiful squigglies!!', '2014-03-01 22:08:56.000000', NULL, 1),
(7183724, 1104262, 30982, '<td valign="top">I like seeing this place in B&amp;W.  The rhythm of it seems to show through better that way.</td>', 'I like seeing this place in B&W.  The rhythm of it seems to show through better that way.', '2014-03-01 22:46:03.000000', NULL, 1),
(7183727, 1104115, 30982, '<td valign="top">Excellent street shot.  I like that you left the box in the upper left corner in the shot - it serves as a sun of sorts, to light the frame.</td>', 'Excellent street shot.  I like that you left the box in the upper left corner in the shot - it serves as a sun of sorts, to light the frame.', '2014-03-01 22:46:41.000000', NULL, 1),
(7183731, 1104178, 30982, '<td valign="top">Wonderful flow.  You could, if you wanted, leave out the left quarter and you''d still have that wonderful sense of flying out of the frame, but you''d lose the vertical interruption of the red post.  Still, I very much enjoy the photograph.</td>', 'Wonderful flow.  You could, if you wanted, leave out the left quarter and you''d still have that wonderful sense of flying out of the frame, but you''d lose the vertical interruption of the red post.  Still, I very much enjoy the photograph.', '2014-03-01 22:48:17.000000', NULL, 1),
(7183735, 1104220, 30982, '<td valign="top">An interesting sense of adventure, even without your title.</td>', 'An interesting sense of adventure, even without your title.', '2014-03-01 22:48:37.000000', NULL, 1),
(7183738, 1102984, 30982, '<td valign="top">I love single trees.  I especially love them in fields that remind me of Germany, with the golden rape seed on the left.</td>', 'I love single trees.  I especially love them in fields that remind me of Germany, with the golden rape seed on the left.', '2014-03-01 22:49:18.000000', NULL, 1),
(7183740, 1104113, 30982, '<td valign="top">Oh what a great find!  Her face is framed perfectly, too.  Excellent street shot!</td>', 'Oh what a great find!  Her face is framed perfectly, too.  Excellent street shot!', '2014-03-01 22:49:47.000000', NULL, 1),
(7183742, 1103921, 30982, '<td valign="top">The poles have an alien feeling to them... makes the whole thing just a bit surreal!</td>', 'The poles have an alien feeling to them... makes the whole thing just a bit surreal!', '2014-03-01 22:50:12.000000', NULL, 1),
(7183745, 1102689, 30982, '<td valign="top">An interesting set of lines and shapes - nicely seen!</td>', 'An interesting set of lines and shapes - nicely seen!', '2014-03-01 22:50:50.000000', NULL, 1),
(7183750, 1102892, 30982, '<td valign="top">I do love lonely old trees n the middle of fields.  I like your almost but not quite monochromatic presentation, but there appears to be a bit of a halo around the tree, as though you''ve darkened the sky in post.  It''s a valid editing treatment, but one that to me seems to limit the tree, to unnaturally contain it.</td>', 'I do love lonely old trees n the middle of fields.  I like your almost but not quite monochromatic presentation, but there appears to be a bit of a halo around the tree, as though you''ve darkened the sky in post.  It''s a valid editing treatment, but one that to me seems to limit the tree, to unnaturally contain it.', '2014-03-01 22:52:10.000000', NULL, 1),
(7183752, 1103743, 30982, '<td valign="top">It almost feels as though a frame''s caught midway in a film reel.</td>', 'It almost feels as though a frame''s caught midway in a film reel.', '2014-03-01 22:52:56.000000', NULL, 1),
(7183754, 1102670, 30982, '<td valign="top">Indeed, the snowman is the first thing that caught my eye.  A charming photograph - I quite like it, thanks!!</td>', 'Indeed, the snowman is the first thing that caught my eye.  A charming photograph - I quite like it, thanks!!', '2014-03-01 22:53:35.000000', NULL, 1),
(7183755, 1104027, 30982, '<td valign="top">Haunting light!</td>', 'Haunting light!', '2014-03-01 22:53:57.000000', NULL, 1),
(7183787, 1104106, 30982, '<td valign="top">I like the small acolytes under the master, reaching up.</td>', 'I like the small acolytes under the master, reaching up.', '2014-03-01 23:13:03.000000', NULL, 1),
(7183788, 1104264, 30982, '<td valign="top">Nicely in-the-moment.  Fleeting and memorialized all at once.</td>', 'Nicely in-the-moment.  Fleeting and memorialized all at once.', '2014-03-01 23:13:30.000000', NULL, 1),
(7183792, 1104217, 30982, '<td valign="top">A cross between crumpled paper and a richly toned sketch.</td>', 'A cross between crumpled paper and a richly toned sketch.', '2014-03-01 23:14:22.000000', NULL, 1),
(7183794, 1104113, 114285, '<td valign="top">If she was looking out the window it would of impacted me more, but as is I don''t get a strong feeling for this one, I want too but it''s just not there.<br/> <br/>But it might later, I might revisit this one.</td>', 'If she was looking out the window it would of impacted me more, but as is I don''t get a strong feeling for this one, I want too but it''s just not there. But it might later, I might revisit this one.', '2014-03-01 23:14:33.000000', NULL, 1),
(7183796, 1103706, 30982, '<td valign="top">So nice that you found a time machine and popped back with this for us.  Both hope and hopeless reside here.</td>', 'So nice that you found a time machine and popped back with this for us.  Both hope and hopeless reside here.', '2014-03-01 23:15:48.000000', NULL, 1),
(7183797, 1102801, 30982, '<td valign="top">So tragic and yet so beautiful!</td>', 'So tragic and yet so beautiful!', '2014-03-01 23:16:11.000000', NULL, 1),
(7183800, 1104139, 30982, '<td valign="top">A nice presentation - seems rather shy, doesn''t it?</td>', 'A nice presentation - seems rather shy, doesn''t it?', '2014-03-01 23:17:03.000000', NULL, 1),
(7183804, 1103785, 30982, '<td valign="top">Such intensity from the horse; such calm from the rider.</td>', 'Such intensity from the horse; such calm from the rider.', '2014-03-01 23:18:12.000000', NULL, 1),
(7183806, 1103249, 30982, '<td valign="top">Ha!  What a fun shot!</td>', 'Ha!  What a fun shot!', '2014-03-01 23:18:22.000000', NULL, 1),
(7183809, 1102976, 30982, '<td valign="top">Indeed.  Sad and gorgeous all at once.  But it gives me comfort how they seem to be placed in pairs, to keep each other company.</td>', 'Indeed.  Sad and gorgeous all at once.  But it gives me comfort how they seem to be placed in pairs, to keep each other company.', '2014-03-01 23:19:12.000000', NULL, 1),
(7183810, 1104229, 114285, '<td valign="top">This looks like some sort of spinal xray, really great stuff.</td>', 'This looks like some sort of spinal xray, really great stuff.', '2014-03-01 23:19:26.000000', NULL, 1),
(7183811, 1102776, 30982, '<td valign="top">Wonderful sweep of light!</td>', 'Wonderful sweep of light!', '2014-03-01 23:19:26.000000', NULL, 1),
(7183813, 1102594, 114285, '<td valign="top">Interesting take on the challenge, loving what you saw through your lens, isn''t that what photography is!</td>', 'Interesting take on the challenge, loving what you saw through your lens, isn''t that what photography is!', '2014-03-01 23:20:24.000000', NULL, 1),
(7183814, 1104065, 30982, '<td valign="top">Such a grand view!!  So enchanting to see from the bee''s perspective.  How lovely the world is!</td>', 'Such a grand view!!  So enchanting to see from the bee''s perspective.  How lovely the world is!', '2014-03-01 23:20:35.000000', NULL, 1),
(7183815, 1103013, 30982, '<td valign="top">A lovely grand view where the sun is so kindly reaching out to invite us in.</td>', 'A lovely grand view where the sun is so kindly reaching out to invite us in.', '2014-03-01 23:20:56.000000', NULL, 1),
(7183821, 1102823, 30982, '<td valign="top">I like the use of negative space.  Do try to remember to provide a title, or use "Untitled" if you wish.</td>', 'I like the use of negative space.  Do try to remember to provide a title, or use "Untitled" if you wish.', '2014-03-01 23:30:27.000000', NULL, 1),
(7183824, 1104247, 30982, '<td valign="top">I like the long view down the alley, and I understand you''re highlighting the umbrellas, but I''m not a big fan of selective color.</td>', 'I like the long view down the alley, and I understand you''re highlighting the umbrellas, but I''m not a big fan of selective color.', '2014-03-01 23:32:21.000000', NULL, 1),
(7183827, 1103715, 30982, '<td valign="top">Very well seen - lovely graphic and good color tones.  Has a great rhythm to it.</td>', 'Very well seen - lovely graphic and good color tones.  Has a great rhythm to it.', '2014-03-01 23:33:24.000000', NULL, 1),
(7183829, 1102662, 30982, '<td valign="top">And I do like the way your worlds blended!</td>', 'And I do like the way your worlds blended!', '2014-03-01 23:33:44.000000', NULL, 1),
(7183830, 1104013, 30982, '<td valign="top">A sense of fragility and perhaps longing.  And sadness.</td>', 'A sense of fragility and perhaps longing.  And sadness.', '2014-03-01 23:34:15.000000', NULL, 1),
